import $ from '../src/shell.js';
import { suite, test } from 'node:test';
import TestBattery, { TestDoneCallback } from 'test-battery';
import 'source-map-support/register.js';

// src/lib/shell.test.ts

suite('shell $ function', () => {

  TestBattery.test('Simple commands', battery => {
    battery.test('executes a simple command and returns output')
      .value('hello')
      .value($`echo -n hello`)
      .equal;
    battery.test('executes a simple command and catches wrong output')
      .value('not hello')
      .value($`echo -n hello`)
      .not.equal;
    battery.test('executes a simple command with a quoted string')
      .value('hello  world')
      .value($`echo -n "hello  world"`)
      .equal;
    battery.test('executes a simple command with an escaped space')
      .value('hel lo world')
      .value($`echo -n hel\ lo\ world`)
      .equal;
  });

  TestBattery.test('Commands from template strings', async battery => {
    battery.test('executes a simple command with a template string')
      .value('hello world')
      .value($`echo -n hello ${'wor'}ld`)
      .equal;
    battery.test('executes a command with multiple template values')
      .value('hello world')
      .value($`echo -n hello ${'wo'}r${'ld'}`)
      .equal;
  });

  TestBattery.test('Command with spawn options', battery => {
    battery.test('executes a command with custom spawn options')
      .value('12345')
      .value($({ shell: true })`for i in {1..5}; do printf "%s" $i; done`)
      .equal;
  });

  if (process.env.REMOTE_SSH) {
    TestBattery.test('Handles remote commands', async battery => {
      battery.test('executes a remote command via SSH')
        .value('workload')
        .value((await $({ shell: `ssh ${process.env.REMOTE_SSH}` })`hostname | sed -e 's/-.*//'`).trim())
        .equal;
    });
  } else {
    test.skip('REMOTE_SSH environment variable not set, skipping remote command tests');
  }
});